// lib/scroll-store.ts  (mutable, never React state)
import type Lenis from 'lenis'
export const scrollStore = { lenis: null as Lenis | null, centers: [] as number[], velocity: 0 }
export function chapterFromY(y: number, c = scrollStore.centers) {
  if (c.length < 2 || y <= c[0]) return 0
  for (let i = 0; i < c.length - 1; i++) if (y < c[i + 1]) return i + (y - c[i]) / (c[i + 1] - c[i])
  return c.length - 1
}

// components/three/RoadRig.tsx
'use client'
import * as THREE from 'three'
import { useMemo, useRef } from 'react'
import { useFrame } from '@react-three/fiber'
import { easing } from 'maath'
import { scrollStore, chapterFromY } from '@/lib/scroll-store'

const STATIONS = [0, 0.16, 0.38, 0.6, 0.8, 1]   // arc-length u where the subject parks, one per section
const HOLD = 0.25                                 // parked for 25% either side of a section centre
const smoother = (a: number, b: number, x: number) => { const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1); return t * t * t * (t * (6 * t - 15) + 10) }
const stationU = (ch: number) => { const i = Math.min(Math.floor(ch), STATIONS.length - 2); return THREE.MathUtils.lerp(STATIONS[i], STATIONS[i + 1], smoother(HOLD, 1 - HOLD, ch - i)) }
const _p = new THREE.Vector3(), _t = new THREE.Vector3(), _cam = new THREE.Vector3(), _aim = new THREE.Vector3()
const CAM_UP = new THREE.Vector3(0, 2.4, 0)

export function RoadRig({ curve, subject }: { curve: THREE.CatmullRomCurve3; subject: React.RefObject<THREE.Group> }) {
  const len = useMemo(() => curve.getLength(), [curve])
  const rig = useRef({ u: 0 })                 // RENDERED progress (maath keeps velocity in rig.__damp)
  const look = useRef(new THREE.Vector3())
  useFrame((state, delta) => {
    const dt = Math.min(delta, 1 / 20)
    const y = scrollStore.lenis?.targetScroll ?? window.scrollY     // raw INTENT
    const target = stationU(chapterFromY(y))                         // TARGET progress
    const gap = Math.abs(target - rig.current.u)
    const maxWorld = 14 * (1 + 3 * Math.max(0, gap - 0.15))        // units/s, catch-up when far behind
    easing.damp(rig.current, 'u', target, 0.42, dt, maxWorld / len)  // smoothTime 0.42 s, speed cap
    const u = THREE.MathUtils.clamp(rig.current.u, 0, 1)
    curve.getPointAt(u, _p); curve.getTangentAt(u, _t)
    const s = subject.current!
    s.position.copy(_p)
    easing.dampLookAt(s, _aim.copy(_p).add(_t), 0.12, dt)           // smoothed steering
    _cam.copy(_p).addScaledVector(_t, -7).add(CAM_UP)
    easing.damp3(state.camera.position, _cam, 0.6, dt)              // lazier chase camera
    easing.damp3(look.current, _aim.copy(_p).addScaledVector(_t, 3), 0.3, dt)
    state.camera.lookAt(look.current)
  })
  return null
}

export function profileStep(s: { x: number; v: number }, target: number, dt: number, maxV: number, maxA: number) {
  const steps = Math.max(1, Math.ceil(dt * 120)), h = dt / steps
  for (let k = 0; k < steps; k++) {
    const d = target - s.x
    const want = Math.sign(d) * Math.min(maxV, Math.sqrt(2 * maxA * Math.abs(d)), Math.abs(d) / h)
    s.v += THREE.MathUtils.clamp(want - s.v, -maxA * h, maxA * h)
    s.x += s.v * h
  }
}
// in useFrame: profileStep(rig.current, target, dt, 14 / len, 9 / len)  // 14 u/s cruise, 9 u/s^2 accel

'use client'
import { ReactLenis, type LenisRef } from 'lenis/react'
import 'lenis/dist/lenis.css'
import { useEffect, useRef } from 'react'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { scrollStore } from '@/lib/scroll-store'
gsap.registerPlugin(ScrollTrigger)

export function SmoothScroll({ children }: { children: React.ReactNode }) {
  const ref = useRef<LenisRef>(null)
  useEffect(() => {
    const lenis = ref.current?.lenis
    if (!lenis) return
    scrollStore.lenis = lenis
    const off = lenis.on('scroll', (l) => { ScrollTrigger.update(); scrollStore.velocity = l.velocity })
    const tick = (t: number) => lenis.raf(t * 1000)
    gsap.ticker.add(tick)
    gsap.ticker.lagSmoothing(0)
    const measure = () => {
      scrollStore.centers = Array.from(document.querySelectorAll<HTMLElement>('[data-chapter]')).map((el) => {
        const r = el.getBoundingClientRect(); return r.top + window.scrollY + r.height / 2 - window.innerHeight / 2
      })
    }
    ScrollTrigger.addEventListener('refresh', measure); measure()
    document.fonts?.ready.then(() => ScrollTrigger.refresh())
    return () => { gsap.ticker.remove(tick); off(); ScrollTrigger.removeEventListener('refresh', measure); scrollStore.lenis = null }
  }, [])
  return (
    <ReactLenis root ref={ref} options={{ autoRaf: false, lerp: 0.12, anchors: true, syncTouch: false }}>
      {children}
    </ReactLenis>
  )
}

// Optional strict single loop: <Canvas frameloop='never'> + this inside it
function GsapDrivenFrames() {
  const advance = useThree((s) => s.advance)
  useEffect(() => { const t = (time: number) => advance(time); gsap.ticker.add(t); return () => gsap.ticker.remove(t) }, [advance])
  return null
}

type Pose = { cam: THREE.Vector3; aim: THREE.Vector3; fov: number }
const rail = (pts: THREE.Vector3[]) => new THREE.CatmullRomCurve3(pts, false, 'centripetal')
const _c = new THREE.Vector3(), _a = new THREE.Vector3()

export function CameraRail({ poses }: { poses: Pose[] }) {
  const camRail = useMemo(() => rail(poses.map((p) => p.cam)), [poses])
  const aimRail = useMemo(() => rail(poses.map((p) => p.aim)), [poses])
  const st = useRef({ ch: 0 })
  useFrame((state, delta) => {
    const dt = Math.min(delta, 1 / 20), n = poses.length - 1
    const raw = chapterFromY(scrollStore.lenis?.targetScroll ?? window.scrollY)
    easing.damp(st.current, 'ch', raw, 0.5, dt, 1.2)          // max 1.2 chapters/s
    const i = Math.min(Math.floor(st.current.ch), n - 1)
    const local = smoother(0.2, 0.8, st.current.ch - i)        // hold around each keyframe
    const t = (i + local) / n
    camRail.getPoint(t, _c); aimRail.getPoint(t, _a)           // passes exactly through keyframes
    state.camera.position.copy(_c); state.camera.lookAt(_a)
    const cam = state.camera as THREE.PerspectiveCamera
    const fov = THREE.MathUtils.lerp(poses[i].fov, poses[i + 1].fov, local)
    if (Math.abs(cam.fov - fov) > 0.01) { cam.fov = fov; cam.updateProjectionMatrix() }
  })
  return null
}

