// lib/gpu-tier.ts
import { getGPUTier } from '@pmndrs/detect-gpu'
export type Tier = 0 | 1 | 2 | 3
export async function detectTier(): Promise<Tier> {
  try { if (!document.createElement('canvas').getContext('webgl2')) return 0 } catch { return 0 }
  const nav = navigator as Navigator & { deviceMemory?: number; connection?: { saveData?: boolean } }
  const r = await getGPUTier({ benchmarksURL: '/gpu-benchmarks' }).catch(() => null)
  let t = (r?.tier ?? 2) as Tier
  if (r?.isMobile) t = Math.min(t, 2) as Tier
  if ((nav.deviceMemory ?? 8) <= 4 || nav.connection?.saveData) t = Math.min(t, 1) as Tier
  return t
}
export const QUALITY = {
  1: { tier: 1, dpr: [1, 1.25], post: false, ao: false, glass: 'fake',  envRes: 64,  seg: 0.5,  shadows: 'blob' },
  2: { tier: 2, dpr: [1, 1.5],  post: true,  ao: false, glass: 'cheap', envRes: 128, seg: 0.75, shadows: 'contact' },
  3: { tier: 3, dpr: [1, 2],    post: true,  ao: true,  glass: 'full',  envRes: 256, seg: 1,    shadows: 'accumulative' },
} as const

