function useFraming() {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera
  const size = useThree((s) => s.size)
  useLayoutEffect(() => {
    const portrait = size.width / size.height < 0.9
    const hFov = THREE.MathUtils.degToRad(portrait ? 58 : 50)
    camera.fov = THREE.MathUtils.clamp(THREE.MathUtils.radToDeg(2 * Math.atan(Math.tan(hFov / 2) / camera.aspect)), 28, 72)
    const ox = portrait ? 0 : -size.width * 0.17   // desktop: subject on right third
    const oy = portrait ? size.height * 0.14 : 0   // phone: subject at ~36% from top
    camera.setViewOffset(size.width, size.height, ox, oy, size.width, size.height)
    camera.updateProjectionMatrix()
    return () => camera.clearViewOffset()
  }, [camera, size])
}
