function Ready() {
  const { gl, scene, camera } = useThree()
  useEffect(() => {
    let alive = true
    gl.compileAsync(scene, camera).then(() => requestAnimationFrame(() => { if (alive) document.documentElement.dataset.stage = 'ready' }))
    return () => { alive = false }
  }, [gl, scene, camera])
  return null
}

