import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js'
const paint = (g: THREE.BufferGeometry, hex: string) => {
  const c = new THREE.Color(hex), n = g.attributes.position.count, a = new Float32Array(n * 3)
  for (let i = 0; i < n; i++) c.toArray(a, i * 3)
  g.setAttribute('color', new THREE.BufferAttribute(a, 3)); return g
}
const profile = [[0, 0], [0.42, 0], [0.55, 0.3], [0.3, 0.7], [0.46, 1.1], [0, 1.25]].map(([x, y]) => new THREE.Vector2(x, y))
export function makeTotem(seg = 1) {
  const s = (n: number) => Math.max(8, Math.round(n * seg))
  return mergeGeometries([
    paint(new THREE.CylinderGeometry(1, 1.15, 0.5, s(64)), '#1d1b4b'),
    paint(new THREE.SphereGeometry(0.7, s(64), s(32)).translate(0, 1, 0), '#ff6b3d'),
    paint(new THREE.TorusGeometry(0.95, 0.12, s(24), s(96)).rotateX(Math.PI / 2).translate(0, 1, 0), '#ffd23f'),
    paint(new THREE.LatheGeometry(profile, s(64)).translate(0, 1.7, 0), '#19c2a0'),
  ])!
}
