  if (!matchMedia('(pointer: fine)').matches) return
  const el = ref.current!
  const xTo = gsap.quickTo(el, 'x', { duration: 0.45, ease: 'power3' }), yTo = gsap.quickTo(el, 'y', { duration: 0.45, ease: 'power3' })
  const move = (e: PointerEvent) => { const r = el.getBoundingClientRect(); xTo((e.clientX - r.left - r.width / 2) * 0.3); yTo((e.clientY - r.top - r.height / 2) * 0.3) }
  const leave = () => { xTo(0); yTo(0) }
  el.addEventListener('pointermove', move); el.addEventListener('pointerleave', leave)
  return () => { el.removeEventListener('pointermove', move); el.removeEventListener('pointerleave', leave) }
}, { scope: ref })

